import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
function collect(dir: string, prefix = ""): Record<string, string> {
  const result: Record<string, string> = {};
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name),
      key = prefix + entry.name;
    if (entry.isDirectory()) Object.assign(result, collect(path, key + "/"));
    else result[key] = readFileSync(path, "utf8");
  }
  return result;
}
writeFileSync(
  "src/baseline.ts",
  "// Generated by npm run bundle:scenario; never include private scenario assets.\nexport const baseline: Record<string,string> = " +
    JSON.stringify(collect("scenario/public"), null, 2) +
    ";\n",
);
